class InventorySystem {
    constructor(weightLimit = 100) {
        this.weightLimit = weightLimit;
        this.items = [];
        this.equippedItems = {};
        this.totalWeight = 0;
    }

    // Add item to inventory
    addItem(item) {
        if (this.totalWeight + item.weight > this.weightLimit) {
            return false; // Not enough space
        }

        this.items.push(item);
        this.totalWeight += item.weight;
        return true;
    }

    // Remove item from inventory
    removeItem(itemName) {
        const index = this.items.findIndex(item => item.name === itemName);
        if (index === -1) return false; // Item not found

        const removedItem = this.items.splice(index, 1)[0];
        this.totalWeight -= removedItem.weight;

        // If item was equipped, unequip it
        if (this.equippedItems[itemName]) {
            delete this.equippedItems[itemName];
        }

        return true;
    }

    // Equip an item
    equipItem(itemName) {
        const item = this.items.find(i => i.name === itemName);
        if (!item || !item.slot) return false; // Item not found or can't be equipped

        // Unequip existing item in same slot
        if (this.equippedItems[item.slot]) {
            this.unequipItem(this.equippedItems[item.slot].name);
        }

        // Equip new item
        this.equippedItems[itemName] = item;
        return true;
    }

    // Unequip an item
    unequipItem(itemName) {
        const item = this.equippedItems[itemName];
        if (!item) return false; // Item not equipped

        delete this.equippedItems[itemName];
        return true;
    }

    // Get total stat modifiers from equipped items
    getStatModifiers() {
        const modifiers = {
            attack: 0,
            defense: 0,
            speed: 0,
            health: 0
        };

        for (const itemName in this.equippedItems) {
            const item = this.equippedItems[itemName];
            if (item.modifiers) {
                for (const stat in item.modifiers) {
                    if (modifiers.hasOwnProperty(stat)) {
                        modifiers[stat] += item.modifiers[stat];
                    }
                }
            }
        }

        return modifiers;
    }

    // Get current inventory info
    getInventoryInfo() {
        return {
            items: this.items.map(item => ({
                name: item.name,
                weight: item.weight,
                slot: item.slot,
                modifiers: item.modifiers
            })),
            equipped: Object.keys(this.equippedItems),
            totalWeight: this.totalWeight,
            weightLimit: this.weightLimit
        };
    }
}

