            modifiersMatch = false;
            break;
        }
    }
    console.log(`Stat modifiers test: ${modifiersMatch ? 'PASS' : 'FAIL'}`);

    console.log(`Overall test: ${actualWeight === expectedWeight && 
                  actualEquipped === expectedEquipped && 
                  modifiersMatch ? 'ALL TESTS PASSED' : 'SOME TESTS FAILED'}`);
}

// Run the demo
runDemo();
