// Turn-based combat system with initiative order and status effects
class CombatSystem {
    constructor() {
        this.combatants = [];
        this.initiativeOrder = [];
        this.currentTurn = 0;
        this.isCombatActive = false;
    }

    // Add a combatant to the battle
    addCombatant(name, health, maxHealth, attack, defense, speed, statusEffects = []) {
        const combatant = {
            name,
            health,
            maxHealth,
            attack,
            defense,
            speed,
            statusEffects,
            isAlive: true
        };
        this.combatants.push(combatant);
        return combatant;
    }

    // Calculate initiative for all combatants
    calculateInitiative() {
        // Sort by speed (descending) then by random tiebreaker
        this.initiativeOrder = [...this.combatants]
            .filter(c => c.isAlive)
            .sort((a, b) => {
                if (b.speed !== a.speed) {
                    return b.speed - a.speed;
                }
                return Math.random() - 0.5; // Random tiebreaker
            });

        this.currentTurn = 0;
        return this.initiativeOrder;
    }

    // Apply a status effect to a combatant
    applyStatusEffect(targetName, effectType, duration = 1) {
        const target = this.combatants.find(c => c.name === targetName);
        if (!target || !target.isAlive) return false;

        // Check if effect already exists
        const existingEffectIndex = target.statusEffects.findIndex(e => e.type === effectType);
        if (existingEffectIndex >= 0) {
            // Extend duration if effect exists
            target.statusEffects[existingEffectIndex].duration += duration;
        } else {
            // Add new effect
            target.statusEffects.push({
                type: effectType,
                duration: duration
            });
        }
        return true;
    }

    // Remove expired status effects
    removeExpiredEffects() {
        this.combatants.forEach(combatant => {
            combatant.statusEffects = combatant.statusEffects.filter(effect => effect.duration > 0);
        });
    }

    // Process status effects for current turn
    processStatusEffects() {
        this.combatants.forEach(combatant => {
            if (!combatant.isAlive) return;

            // Process each active effect
            combatant.statusEffects.forEach(effect => {
                switch (effect.type) {
                    case 'poison':
                        // Apply poison damage
                        const poisonDamage = Math.max(1, Math.floor(combatant.maxHealth * 0.1));
                        combatant.health = Math.max(0, combatant.health - poisonDamage);
                        console.log(`${combatant.name} takes ${poisonDamage} poison damage!`);
                        break;
                    case 'stun':
                        // Stunned combatants skip their turn
                        console.log(`${combatant.name} is stunned and skips their turn!`);
                        break;
                }
                // Reduce duration
                effect.duration--;
            });
        });
    }

    // Attack another combatant
    attack(attackerName, defenderName) {
        const attacker = this.combatants.find(c => c.name === attackerName);
        const defender = this.combatants.find(c => c.name === defenderName);

        if (!attacker || !defender || !attacker.isAlive || !defender.isAlive) {
            return false;
        }

        // Check if attacker is stunned
        const stunEffect = attacker.statusEffects.find(e => e.type === 'stun');
        if (stunEffect) {
            console.log(`${attacker.name} is stunned and cannot attack!`);
            return false;
        }

        // Calculate damage
        const damage = Math.max(1, attacker.attack - defender.defense);
        defender.health = Math.max(0, defender.health - damage);

        console.log(`${attacker.name} attacks ${defender.name} for ${damage} damage!`);

        // Check if defender died
        if (defender.health <= 0) {
            defender.isAlive = false;
            console.log(`${defender.name} has been defeated!`);
        }

        return true;
    }

    // End the current turn
    endTurn() {
        // Process status effects
        this.processStatusEffects();

        // Remove expired effects
        this.removeExpiredEffects();

        // Move to next combatant
        this.currentTurn = (this.currentTurn + 1) % this.initiativeOrder.length;

        // Check if combat should continue
        this.checkCombatEnd();

        return this.getCurrentCombatant();
    }

    // Get the combatant whose turn it currently is
    getCurrentCombatant() {
        if (this.initiativeOrder.length === 0) return null;
        return this.initiativeOrder[this.currentTurn];
    }

    // Check if combat has ended
    checkCombatEnd() {
        const aliveCombatants = this.combatants.filter(c => c.isAlive);
        if (aliveCombatants.length <= 1) {
            this.isCombatActive = false;
            if (aliveCombatants.length === 1) {
                console.log(`Combat ends! ${aliveCombatants[0].name} wins!`);
            } else {
                console.log("Combat ends in a draw!");
            }
        }
    }

    // Start combat
    startCombat() {
        this.calculateInitiative();
        this.isCombatActive = true;
        console.log("Combat begins!");
        console.log("Initiative order:", this.initiativeOrder.map(c => c.name).join(", "));
        return this.getCurrentCombatant();
    }

    // Get combat state for debugging
    getCombatState() {
        return {
            combatants: this.combatants,
            initiativeOrder: this.initiativeOrder,
            currentTurn: this.currentTurn,
            isCombatActive: this.isCombatActive
        };
    }
}

