// Crafting System Module
const CraftingSystem = (function() {
    // Private variables
    let inventory = {};
    let recipes = {};

    // Private helper function to check if player has required items
    function canCraft(recipe) {
        for (const [item, quantity] of Object.entries(recipe.ingredients)) {
            if ((inventory[item] || 0) < quantity) {
                return false;
            }
        }
        return true;
    }

    // Private helper function to consume ingredients
    function consumeIngredients(recipe) {
        for (const [item, quantity] of Object.entries(recipe.ingredients)) {
            inventory[item] -= quantity;
            if (inventory[item] <= 0) {
                delete inventory[item];
            }
        }
    }

    // Public API
    return {
        // Initialize inventory with starting items
        init: function(startingItems = {}) {
            inventory = { ...startingItems };
            return this;
        },

        // Add items to inventory
        addItem: function(item, quantity = 1) {
            inventory[item] = (inventory[item] || 0) + quantity;
            return this;
        },

        // Remove items from inventory
        removeItem: function(item, quantity = 1) {
            if (inventory[item]) {
                inventory[item] -= quantity;
                if (inventory[item] <= 0) {
                    delete inventory[item];
                }
            }
            return this;
        },

        // Register a new recipe
        addRecipe: function(name, ingredients, result, resultQuantity = 1) {
            recipes[name] = {
                ingredients,
                result,
                resultQuantity
            };
            return this;
        },

        // Attempt to craft an item
        craft: function(recipeName) {
            const recipe = recipes[recipeName];
            if (!recipe) {
                throw new Error(`Recipe "${recipeName}" not found`);
            }

            if (!canCraft(recipe)) {
                throw new Error(`Insufficient ingredients to craft "${recipeName}"`);
            }

            consumeIngredients(recipe);
            this.addItem(recipe.result, recipe.resultQuantity);

            return {
                success: true,
                recipe: recipeName,
                result: recipe.result,
                quantity: recipe.resultQuantity
            };
        },

        // Get current inventory
        getInventory: function() {
            return { ...inventory };
        },

        // Get available recipes
        getRecipes: function() {
            return { ...recipes };
        },

        // Check if can craft a specific recipe
        canCraft: function(recipeName) {
            const recipe = recipes[recipeName];
            return recipe ? canCraft(recipe) : false;
        }
    };
})();

