// Branching Dialogue System with World Flags
class DialogueSystem {
    constructor() {
        this.worldFlags = new Map();
        this.currentNode = null;
    }

    // Set a world flag to true/false
    setFlag(flagName, value) {
        this.worldFlags.set(flagName, value);
    }

    // Check if a world flag is true
    hasFlag(flagName) {
        return this.worldFlags.get(flagName) === true;
    }

    // Initialize the dialogue system with a starting node
    init(startNodeId) {
        this.currentNode = this.nodes[startNodeId];
        return this.currentNode.text;
    }

    // Process a choice selection
    choose(choiceIndex) {
        if (!this.currentNode || !this.currentNode.choices || choiceIndex < 0 || choiceIndex >= this.currentNode.choices.length) {
            return "Invalid choice.";
        }

        const choice = this.currentNode.choices[choiceIndex];

        // Apply any flag changes from this choice
        if (choice.setFlags) {
            for (const [flag, value] of Object.entries(choice.setFlags)) {
                this.setFlag(flag, value);
            }
        }

        // Move to next node
        this.currentNode = this.nodes[choice.nextNode];
        return this.currentNode.text;
    }

    // Get available choices for current node
    getChoices() {
        if (!this.currentNode || !this.currentNode.choices) {
            return [];
        }
        return this.currentNode.choices.map(choice => choice.text);
    }

    // Check if we've reached an ending node
    isEnding() {
        return this.currentNode && this.currentNode.isEnding;
    }

    // Define all dialogue nodes
